PRAGMA foreign_keys = ON;
CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT NOT NULL, brand TEXT NOT NULL, category TEXT NOT NULL, detail TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents>=0), price_source TEXT NOT NULL DEFAULT 'estimate' CHECK(price_source IN ('photo','estimate','fixed')), stock INTEGER CHECK(stock IS NULL OR stock>=0), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), data_json TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK(id=1), data_json TEXT NOT NULL);
INSERT INTO settings VALUES(1,'{"storeName":"MDM Supplements","phone":"0618194707","instagram":"https://www.instagram.com/mdm_supplements/","freeShipping":true,"shippingFee":0,"orderNotice":"Paiement à la livraison. Livraison offerte partout au Maroc."}');
CREATE TABLE orders (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, idempotency_key TEXT NOT NULL UNIQUE, request_hash TEXT NOT NULL, customer_name TEXT NOT NULL, phone TEXT NOT NULL, city TEXT NOT NULL, address TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents>=0), shipping_cents INTEGER NOT NULL CHECK(shipping_cents>=0), total_cents INTEGER NOT NULL CHECK(total_cents=subtotal_cents+shipping_cents), status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','confirmed','preparing','shipped','delivered','cancelled')), payment_method TEXT NOT NULL DEFAULT 'cod', revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX orders_created ON orders(created_at DESC);
CREATE INDEX orders_status ON orders(status,created_at DESC);
CREATE INDEX orders_phone ON orders(phone);
CREATE TABLE order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, detail TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99), unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0), price_source TEXT NOT NULL, UNIQUE(order_id,product_id));
CREATE TABLE order_history (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL REFERENCES orders(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TRIGGER check_order_item BEFORE INSERT ON order_items BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM products WHERE id=NEW.product_id AND active=1) THEN RAISE(ABORT,'PRODUCT_UNAVAILABLE') END;
 SELECT CASE WHEN (SELECT price_cents FROM products WHERE id=NEW.product_id)!=NEW.unit_price_cents THEN RAISE(ABORT,'PRICE_CHANGED') END;
 SELECT CASE WHEN (SELECT stock FROM products WHERE id=NEW.product_id) IS NOT NULL AND (SELECT stock FROM products WHERE id=NEW.product_id)<NEW.quantity THEN RAISE(ABORT,'OUT_OF_STOCK') END;
END;
CREATE TRIGGER reserve_stock AFTER INSERT ON order_items BEGIN UPDATE products SET stock=stock-NEW.quantity, revision=revision+1 WHERE id=NEW.product_id AND stock IS NOT NULL; END;
CREATE TRIGGER order_created AFTER INSERT ON orders BEGIN INSERT INTO order_history(order_id,status,created_at) VALUES(NEW.id,NEW.status,NEW.created_at); END;
CREATE TRIGGER order_status_changed AFTER UPDATE OF status ON orders WHEN NEW.status!=OLD.status BEGIN
 INSERT INTO order_history(order_id,status,created_at) VALUES(NEW.id,NEW.status,NEW.updated_at);
 UPDATE products SET stock=stock+(SELECT quantity FROM order_items WHERE order_id=NEW.id AND product_id=products.id),revision=revision+1 WHERE NEW.status='cancelled' AND OLD.status!='cancelled' AND stock IS NOT NULL AND id IN (SELECT product_id FROM order_items WHERE order_id=NEW.id);
END;
